'use strict';
const labels={unknown:'ยังไม่มีข้อมูลล่าสุด',clear:'รถยนต์สามารถสัญจรได้',flood:'รถยนต์ไม่สามารถสัญจรได้',closed:'ปิด / อันตราย'};
const colors={unknown:'#87979f',clear:'#22966d',flood:'#8054d6',closed:'#dc514d'};
let reports={};
async function api(url,options){const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw Error(data.error||'ติดต่อระบบไม่ได้');return data}
async function refreshReports(){const snapshot=await api('/api/reports');for(const key of Object.keys(reports)){if(!Object.hasOwn(snapshot,key))delete reports[key]}for(const [key,entries] of Object.entries(snapshot)){if(!reports[key]||entries[0]?.submittedAt>history(key)[0]?.submittedAt)reports[key]=entries}if(collection)decorate()}
let reporterId;try{reporterId=localStorage.getItem('klaeng-demo-reporter-v1');if(!reporterId){reporterId=crypto.randomUUID();localStorage.setItem('klaeng-demo-reporter-v1',reporterId)}}catch{reporterId=crypto.randomUUID()}
function history(key){const value=reports[key];return (Array.isArray(value)?value:value?[value]:[]).filter(r=>Number.isFinite(r.time)&&['clear','flood','closed'].includes(r.status)).slice().sort((a,b)=>b.time-a.time||(b.submittedAt||0)-(a.submittedAt||0))}
let collection=null,selected=null,pinning=false;
const detail=document.getElementById('detail');
function state(f){const r=history(f.properties.key)[0];if(!r||Date.now()-r.time>=3600000)return 'unknown';return r.status}
function decorate(){for(const f of collection.features)f.properties.status=state(f);map.getSource('roads')?.setData(collection)}
function html(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e}
async function choose(f){selected=collection.features.find(x=>x.id===f.id);if(!selected)return;document.body.classList.add('has-selection');map.resize();map.setFilter('selected-shadow',['==',['id'],selected.id]);map.setFilter('selected-road',['==',['id'],selected.id]);showDetail();const key=selected.properties.key;try{const data=await api('/api/roads/'+encodeURIComponent(key));reports[key]=data.reports;decorate();if(selected?.properties.key===key){selected.properties.reporterCount=data.reporterCount;selected.properties.reportCount=data.reportCount;showDetail()}}catch{if(selected?.properties.key===key)detail.append(html('p','error','โหลดประวัติไม่ได้ โปรดลองเลือกถนนอีกครั้ง'))}}
function nearestRoad(features,point){let best=null,bestDistance=Infinity;for(const feature of features){const lines=feature.geometry.type==='MultiLineString'?feature.geometry.coordinates:[feature.geometry.coordinates];for(const line of lines){for(let i=1;i<line.length;i++){const a=map.project(line[i-1]),b=map.project(line[i]);const dx=b.x-a.x,dy=b.y-a.y;const t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/(dx*dx+dy*dy||1)));const distance=(point.x-a.x-t*dx)**2+(point.y-a.y-t*dy)**2;if(distance<bestDistance){bestDistance=distance;best=feature}}}}return best}
function handleRoadClick(e){if(!collection||!map.getLayer('road-hit'))return;const radius=6;const features=map.queryRenderedFeatures([[e.point.x-radius,e.point.y-radius],[e.point.x+radius,e.point.y+radius]],{layers:['road-hit','selected-road']});const road=nearestRoad(features,e.point);if(road)choose(road);else unselect()}
function unselect(){selected=null;document.body.classList.remove('has-selection');map.resize();map.setFilter('selected-shadow',['==',['id'],-1]);map.setFilter('selected-road',['==',['id'],-1]);detail.replaceChildren(html('h2','','เลือกถนนบนแผนที่'),html('p','note','ซูมเข้าแล้วจิ้มช่วงถนนที่ต้องการดู'))}
function showDetail(){const f=selected,entries=history(f.properties.key),r=entries[0],s=state(f);detail.replaceChildren();const top=html('div','detail-top');top.append(html('h2','',f.properties.name+(f.properties.ref?' · '+f.properties.ref:'')));const close=html('button','secondary','ปิด');close.type='button';close.onclick=unselect;top.append(close);detail.append(top);const badge=html('div','status');badge.dataset.status=s;const dot=html('b');dot.style.background=colors[s];badge.append(dot,document.createTextNode(labels[s]));detail.append(badge);
const meta=html('div','meta');meta.textContent=r?'พบเห็น: '+new Date(r.time).toLocaleString('th-TH')+(state(f)==='unknown'?' · ข้อมูลเก่าแล้ว':''):'ยังไม่มีรายงานสำหรับช่วงนี้';detail.append(meta);
const form=html('form');const slabel=html('label','','สภาพที่พบเห็น');slabel.htmlFor='status';const select=html('select');select.id='status';select.required=true;select.append(new Option('เลือกสภาพถนน',''));for(const k of ['clear','flood','closed'])select.append(new Option(labels[k],k));const tlabel=html('label','','เวลาที่พบเห็น');tlabel.htmlFor='observed';const time=html('input');time.id='observed';time.type='datetime-local';time.required=true;const local=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);time.value=local;time.max=local;const nlabel=html('label','','รายละเอียดเพิ่มเติม (ไม่บังคับ)');nlabel.htmlFor='note';const note=html('textarea');note.id='note';note.rows=2;note.maxLength=300;note.placeholder='เช่น หน้าตลาด น้ำกำลังเพิ่ม';const button=html('button','primary','ส่งรายงาน');button.type='submit';const message=html('div');message.id='message';message.setAttribute('role','status');const options=html('fieldset');options.append(html('legend','','สภาพถนนที่คุณพบ'));const choices=html('div','status-options');for(const k of ['clear','flood','closed']){const label=html('label','status-option');const radio=html('input');radio.type='radio';radio.name='road-status';radio.value=k;radio.required=true;radio.onchange=()=>{select.value=k};const dot=html('b');dot.style.background=colors[k];label.append(radio,dot,document.createTextNode(labels[k]));choices.append(label)}options.append(choices);form.append(options,tlabel,time,nlabel,note,button);form.onsubmit=async e=>{e.preventDefault();const ts=new Date(time.value).getTime();if(!['clear','flood','closed'].includes(select.value)||!Number.isFinite(ts)||ts>Date.now()){message.className='error';message.textContent='โปรดเลือกสถานะและเวลาที่ไม่ใช่อนาคต';return}button.disabled=true;try{await api('/api/reports',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),roadKey:f.properties.key,reporterId,status:select.value,time:ts,note:note.value.trim()})});const data=await api('/api/roads/'+encodeURIComponent(f.properties.key));reports[f.properties.key]=data.reports;f.properties.reporterCount=data.reporterCount;f.properties.reportCount=data.reportCount;decorate();if(selected?.id===f.id){showDetail();document.getElementById('message').textContent='ส่งรายงานแล้ว ทุกคนดูข้อมูลนี้ได้'}}catch(err){message.className='error';message.textContent=err.message}finally{button.disabled=false}};const panel=html('details','report-panel');panel.append(html('summary','','＋ รายงานสภาพถนน'),form);detail.append(panel,message,renderTimeline(entries))}
const map=new maplibregl.Map({container:'map',style:'https://tiles.openfreemap.org/styles/liberty',center:[101.648,12.779],zoom:13.4,attributionControl:true});map.addControl(new maplibregl.NavigationControl(),'top-right');
map.on('load',async()=>{try{const response=await fetch('roads.geojson');if(!response.ok)throw Error('roads');collection=await response.json();await refreshReports();for(const f of collection.features)f.properties.status=state(f);map.addSource('roads',{type:'geojson',data:collection});const labelLayer=map.getStyle().layers.find(layer=>layer.type==='symbol')?.id;const addRoadLayer=layer=>map.addLayer(layer,labelLayer);const color=['match',['get','status'],'clear',colors.clear,'flood',colors.flood,'closed',colors.closed,colors.unknown];addRoadLayer({id:'report-roads',type:'line',source:'roads',layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':color,'line-width':['interpolate',['linear'],['zoom'],10,['case',['==',['get','status'],'unknown'],1,2],14,['case',['==',['get','status'],'unknown'],2,5],17,['case',['==',['get','status'],'unknown'],3,9]],'line-opacity':['case',['==',['get','status'],'unknown'],.25,.85]}});addRoadLayer({id:'road-hit',type:'line',source:'roads',paint:{'line-color':'#000','line-opacity':0,'line-width':24}});addRoadLayer({id:'selected-shadow',type:'line',source:'roads',filter:['==',['id'],-1],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#173b35','line-width':15,'line-blur':5,'line-translate':[0,5],'line-opacity':.6}});addRoadLayer({id:'selected-road',type:'line',source:'roads',filter:['==',['id'],-1],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':color,'line-width':9,'line-translate':[0,-3]}});map.on('click',handleRoadClick);map.on('mouseenter','road-hit',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','road-hit',()=>map.getCanvas().style.cursor='');document.getElementById('loading').textContent=collection.features.length.toLocaleString('th-TH')+' ช่วงถนนจริง · เริ่มที่ตัวเมืองแกลง';registerTools();}catch{const loading=document.getElementById('loading');if(loading){loading.className='note error';loading.textContent='โหลดถนนไม่สำเร็จ โปรดลองเปิดใหม่'}}});
setInterval(()=>{refreshReports().catch(()=>{});},60000);
function registerTools(){if(!document.modelContext?.registerTool)return;try{Promise.resolve(document.modelContext.registerTool({name:'select_road_segment',description:'Select a real road segment on the Klaeng prototype map. Does not submit a report.',inputSchema:{type:'object',properties:{segmentId:{type:'integer'}},required:['segmentId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({segmentId})=>{if(!Number.isInteger(segmentId))throw Error('Invalid segmentId');const f=collection.features.find(x=>x.id===segmentId);if(!f)throw Error('Road segment not found');choose(f);map.flyTo({center:f.geometry.coordinates[0],zoom:15,essential:false});return {segmentId,name:f.properties.name,status:labels[state(f)],demo:true}}})).catch(()=>{})}catch{}}

function renderTimeline(entries){const section=html('section','timeline-section');section.setAttribute('aria-label','ผู้รายงานและประวัติรายงาน');const people=new Set(entries.filter(r=>r.reporterId).map(r=>r.reporterId));const unknown=entries.some(r=>!r.reporterId);section.append(html('h3','','ผู้รายงาน '+(selected?.properties.reporterCount??people.size)+' รหัสเครื่อง · '+(selected?.properties.reportCount??entries.length)+' รายงาน'));section.append(html('p','note','นับตามรหัสเครื่อง ยังไม่ยืนยันจำนวนบุคคล'+(unknown?' · รายงานเดิมบางรายการไม่ทราบผู้รายงาน':'')));if(!entries.length){section.append(html('p','note','ยังไม่มีประวัติรายงานสำหรับช่วงนี้'));return section}const panel=html('details','history-panel');panel.append(html('summary','','ดูประวัติรายงาน ('+entries.length+')'));const list=html('ol','timeline');entries.forEach((entry,i)=>{const item=html('li','timeline-item');item.style.setProperty('--report-color',colors[entry.status]);const heading=html('div','timeline-heading');const stamp=html('time');stamp.dateTime=new Date(entry.time).toISOString();stamp.textContent=new Date(entry.time).toLocaleString('th-TH',{dateStyle:'medium',timeStyle:'short'});heading.append(stamp,html('span','note',i===0?'ล่าสุด':''));item.append(heading,html('div','',labels[entry.status]));item.append(html('p','note',entry.reporterId===reporterId?'คุณ · เครื่องนี้':entry.reporterId?'ผู้รายงาน '+entry.reporterId.slice(0,6):'ไม่ทราบผู้รายงาน'));if(entry.submittedAt)item.append(html('p','note','ส่งรายงาน '+new Date(entry.submittedAt).toLocaleString('th-TH')));if(Date.now()-entry.time>=3600000)item.append(html('span','note','ข้อมูลเก่าแล้ว'));if(entry.note)item.append(html('p','',entry.note));if(entry.photo){const picture=html('img','report-photo');picture.src=entry.photo;picture.alt='รูปประกอบรายงานวันที่ '+stamp.textContent;picture.loading='lazy';item.append(picture)}list.append(item)});panel.append(list);section.append(panel);return section}
